<div class="p-info">Only verified ledger rows contribute to these totals. Settlement approval alone is not a transfer; a settlement is counted as paid only after it is marked settled with a reference.</div>
<div class="p-grid"><section class="p-card"><h3>Verified Eligible Collections</h3><div class="p-value">₹<?= number_format($totals['collections'],2) ?></div></section><section class="p-card"><h3>TCM One Owes Partner</h3><div class="p-value">₹<?= number_format($totals['owes_partner'],2) ?></div><div class="p-trend">Verified entitlement less actual settlements</div></section><section class="p-card"><h3>Partner Owes TCM One</h3><div class="p-value">₹<?= number_format($totals['owes_tcm'],2) ?></div><div class="p-trend">Verified entitlement less actual settlements</div></section><section class="p-card"><h3>Actual Settlements</h3><div class="p-value">₹<?= number_format($totals['settled'],2) ?></div></section></div>
<section class="p-section"><h2>Bilateral ledger</h2><?php if(!$entries): ?><div class="p-empty">No verified or pending financial entries yet.</div><?php else: ?><div class="p-table-wrap"><table class="p-table"><thead><tr><th>Transaction</th><th>Student / Batch</th><th>Collected By</th><th>Gross / Eligible</th><th>Partner / TCM entitlement</th><th>Status</th></tr></thead><tbody><?php foreach($entries as $e1): ?><tr><td>#<?= (int)$e1['id'] ?><br><span class="p-muted"><?= e($e1['description']??$e1['entry_type']) ?></span><br><span class="p-muted"><?= e(date('d M Y',strtotime($e1['created_at']))) ?></span></td><td><?= e($e1['student_name']??'—') ?><br><?= e($e1['batch_name']??'') ?></td><td><?= e(strtoupper($e1['collection_owner'])) ?></td><td>₹<?= number_format((float)$e1['gross_amount'],2) ?><br>₹<?= number_format((float)$e1['eligible_amount'],2) ?></td><td>₹<?= number_format((float)$e1['partner_entitlement'],2) ?><br>₹<?= number_format((float)$e1['tcm_entitlement'],2) ?></td><td><span class="p-pill"><?= e(str_replace('_',' ',$e1['status'])) ?></span></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section>
<section class="p-section"><h2>Settlement history</h2><?php if(!$settlements): ?><div class="p-empty">No settlement records.</div><?php else: ?><div class="p-table-wrap"><table class="p-table"><thead><tr><th>Settlement</th><th>Direction</th><th>Amount</th><th>Status</th><th>Reference</th></tr></thead><tbody><?php foreach($settlements as $s): ?><tr><td>#<?= (int)$s['id'] ?> · <?= e(date('d M Y',strtotime($s['created_at']))) ?></td><td><?= e(str_replace('_',' ',$s['direction'])) ?></td><td>₹<?= number_format((float)$s['amount'],2) ?></td><td><span class="p-pill"><?= e(str_replace('_',' ',$s['status'])) ?></span></td><td><?= e($s['reference']??'—') ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section>
